mapper.select:
select * from (
    select

        (NVL(MID_PLAN_QTY, 0) + NVL(NIGHT_PLAN_QTY, 0) + NVL(DAY_PLAN_QTY, 0)) as daily_total_qty,
        b.MONTH_PLAN_QTY as month_plan,
        b.MONTH_REMAIN_QTY as month_plan_os
    from t_tq_assist_schedule a
    LEFT JOIN (
        select MATERIAL_CODE,MONTH_PLAN_QTY,MONTH_REMAIN_QTY
        from T_TQ_MONTH_PLAN_SURPLUS
        where YEAR=#{year,jdbcType=VARCHAR}
        and MONTH= #{month,jdbcType=VARCHAR}
        and del_flag = '0'
    ) b on a.BEAD_CODE=b.MATERIAL_CODE
    where a.del_flag = '0'
    and a.schedule_date = #{scheduleDate}

        and INSTR(a.bead_code, #{beadCode,jdbcType=VARCHAR}) > 0


        and INSTR(a.steel_ring_code, #{steelRingCode,jdbcType=VARCHAR}) > 0


        and INSTR(a.triangle_glue_code, #{triangleGlueCode,jdbcType=VARCHAR}) > 0


        and INSTR(a.glue_code, #{glueCode,jdbcType=VARCHAR}) > 0

    and a.spec_size = #{specSize}
    and a.production_status = #{productionStatus}
    and a.IS_RELEASE = #{isRelease}
    and INSTR(a.mouth_plate_code, #{mouthPlateCode}) > 0 
    and instr(','||a.machine_id||',', ','||#{machineId}||',')>0
    order by (case when instr(machine_id,',') > 0 then machine_id when machine_id is null or machine_id = '' then '0' else '-1' end) desc/*多个机台 和 没有机台的排在前面*/,a.CREATE_TIME
) t

    order by ${orderStr}
